update public.af_movimientos m set created_at = r.revisado_en from public.af_reportes r, public.af_fincas f where m.reporte_id = r.id and r.revisado_en is not null and f.id = m.finca_id and f.nombre = 'IYOMA PRUEBAS';
update public.af_movimientos m set created_at = (m.fecha + time '09:00' + (abs(hashtext(m.id::text)) % 480) * interval '1 minute') at time zone 'America/Bogota' from public.af_fincas f where m.reporte_id is null and f.id = m.finca_id and f.nombre = 'IYOMA PRUEBAS';
